 function downloadName(){if(mode==='cinema'&&state.cinemaView==='figure')return'cinema-figure';if(mode==='leximpossible'&&state.lexScene!=='region')return'leximpossible-'+state.lexScene;if(mode==='p1'&&state.p1proof!=='strict')return'p1-'+state.p1proof;if(mode==='p2'&&state.p2view==='infinite')return'p2-infinite';if(mode==='p4'&&state.p4view!=='parity')return'p4-'+state.p4view;if(mode==='p5'&&state.p5view==='identity')return'p5-identity';if(mode==='p7'&&state.rule==='closer')return'p7-closer';if(mode==='p8'&&state.p8view==='integer')return'p8-integer';if(mode==='p9'&&state.p9view==='contradiction')return'p9-contradiction';return mode}
 function sync(){clearTimeout(urlTimer);try{const u=new URL(location.href);u.search='';u.searchParams.set('case',mode);for(const[k,v]of Object.entries(state))u.searchParams.set(k,v);history.replaceState(null,'',u)}catch{}const a=document.querySelector('.lesson-end a[download]');if(a)a.href=(location.pathname.includes('/downloads/')||location.protocol==='file:'?'https://microeconomics-atlas-mingze.synb636.chatgpt.site/':'')+'downloads/ch1-'+downloadName()+'.html'}
 function stop(){clearInterval(timer);timer=null;$('play').textContent='逐步演示'}
 function audioStatus(t){audioText=t;const e=$('utility-audio-status');if(e)e.textContent=t}
 function stopAudio(message='已停止声音，可无声操作'){clearInterval(audioClock);audioClock=null;for(const o of audioNodes)try{o.stop()}catch{}audioNodes=[];if(audio){const a=audio;audio=null;a.close().catch(()=>{})}audioStatus(message);if($('u-action-audio'))$('u-action-audio').textContent='点击试听13拍（可停止）'}
 async function playAudio(){if(audio){stopAudio();return}stop();const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio){audioStatus('此浏览器不支持Web Audio，仍可无声查看全部步骤');return}try{const ctx=new Audio();audio=ctx;await ctx.resume();if(audio!==ctx)return;const master=ctx.createGain();master.gain.value=.06;master.connect(ctx.destination);const start=ctx.currentTime+.05,beat=.6;for(const note of shepardPlan(beat))for(const voice of note.voices){const o=ctx.createOscillator(),gain=ctx.createGain(),t=start+note.time;o.type='sine';o.frequency.value=voice.hz;gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(voice.amplitude,t+.05);gain.gain.setValueAtTime(voice.amplitude,t+.46);gain.gain.linearRampToValueAtTime(0,t+.56);o.connect(gain);gain.connect(master);o.start(t);o.stop(t+.58);audioNodes.push(o)}let last=-1;$('u-action-audio').textContent='停止试听';audioStatus('正在播放自主合成音阶，共13拍');audioClock=setInterval(()=>{if(audio!==ctx)return;const elapsed=ctx.currentTime-start;if(elapsed>=13*beat){stopAudio('13拍已结束；首拍与末拍音级相同');return}const note=Math.max(0,Math.min(12,Math.floor(elapsed/beat)));if(note!==last){last=note;state.pitch=note;if($('u-pitch'))$('u-pitch').value=note;if($('uo-pitch'))$('uo-pitch').textContent=note;draw();audioStatus('正在播放第'+(note+1)+'拍，共13拍；音级'+note%12)}},50)}catch{stopAudio('声音未能启动，全部图形与一般论证仍可无声使用')}}
 function refresh(){controls();draw()}
 function advance(){if(['construct','finitelemma','p1','p9'].includes(mode)){const max=mode==='construct'?constructFiniteUtility(pref().relation,state.size).groups.length:mode==='finitelemma'?Math.max(0,state.size-1):3;if(mode==='p9'&&state.p9view==='consistent'){state.p9view='contradiction';state.step=0;refresh();return false}state.step=Math.min(max,state.step+1);refresh();return state.step===max}if(mode==='extrema'){state.kind=state.kind==='minimal'?'maximal':'minimal';refresh();return true}if(mode==='example1'){state.shift=Math.min(8,state.shift+1);refresh();return state.shift===8}if(mode==='utility'||mode==='transform'){if(mode==='transform'&&state.func==='affine'){state.alpha=Math.min(3,state.alpha+.5);refresh();return state.alpha===3}state.power=Math.min(3,Number((state.power+.3).toFixed(2)));refresh();return state.power===3}if(mode==='cinema'){const keys=state.cinemaView==='book'?['row','column']:['fr','fc'],dim=cinemaDimensions(state.cinemaView);state[keys[1]]=state[keys[1]]===1?dim.columns:state[keys[1]]-1;refresh();return state[keys[1]]===1}if(mode==='leximpossible'){if(['intervals','cantor'].includes(state.lexScene)){const max=state.lexScene==='cantor'?2:4;state.proofStep=Math.min(max,state.proofStep+1);refresh();return state.proofStep===max}state.lexScene='intervals';state.proofStep=0;refresh();return false}if(mode==='p2'&&state.p2view==='criterion'){state.target=(Math.min(state.target,Math.max(0,state.size-1))+1)%Math.max(1,state.size);refresh();return state.target===state.size-1}if(mode==='infiniteutility'||mode==='p2'){const domain=mode==='p2'?state.p2Domain:state.infiniteDomain;if(domain==='integers')state.integer=Math.min(10,state.integer+1);else if(domain==='open')state.openPoint=Math.min(.99,state.openPoint+.1);else state.x=Math.min(10,state.x+1);refresh();return state.integer===10||state.x===10}if(mode==='p3'){state.step=(state.step+1)%3;[state.va,state.vb,state.vc]=[[0,.8,1.6],[0,.5,1.6],[0,.8,1]][state.step];refresh();return state.step===2}if(mode==='p4'){state.p4view=state.p4view==='examples'?'parity':state.p4view==='parity'?'partition':'examples';refresh();return state.p4view==='partition'}if(mode==='p5'){state.p5view=state.p5view==='order'?'identity':state.p5view==='identity'?'universal':'order';refresh();return state.p5view==='universal'}if(mode==='p6'){state.pitch=Math.min(12,state.pitch+1);refresh();return state.pitch===12}if(mode==='p7'){state.rule=state.rule==='higher'?'closer':'higher';refresh();return true}if(mode==='p8'){if(state.p8view==='integer')state.k=Math.min(state.gap+1,state.k+1);else state.n=Math.min(200,state.n+1);refresh();return state.p8view==='integer'?state.k===state.gap+1:state.n===200}return true}
 $('fields').addEventListener('input',e=>{const k=e.target.dataset.u;if(!k||e.target.type!=='range')return;stop();if(audio)stopAudio();state[k]=Number(e.target.value);if($('uo-'+k))$('uo-'+k).textContent=fmt(state[k]);draw(true)});
 $('fields').addEventListener('change',e=>{if(e.target.type==='range'){clearTimeout(urlTimer);sync();return}const k=e.target.dataset.u;if(!k)return;stop();if(audio)stopAudio();if(k==='case')mode=e.target.value;else state[k]=ranges[k]?Number(e.target.value):e.target.value;refresh()});
 $('fields').addEventListener('click',e=>{const b=e.target.closest('[data-u-action]');if(!b)return;const action=b.dataset.uAction;if(action==='audio'){playAudio();return}stop();if(audio)stopAudio();if(action==='construct-values'){const p=pref(),c=constructFiniteUtility(p.relation,p.n);c.values.forEach((v,i)=>state['u'+L(i)]=v)}if(action==='cinema-edge'){const book=state.cinemaView==='book',d=cinemaDimensions(state.cinemaView),r=Math.min(d.rows-1,book?state.row:state.fr);if(book)Object.assign(state,{row:r,column:1,br:r+1,bc:d.columns});else Object.assign(state,{fr:r,fc:1,gr:r+1,gc:d.columns})}if(action==='lex-primary')Object.assign(state,{zx:.2,zy:.9,px:.3,py:.1});if(action==='lex-secondary')Object.assign(state,{zx:.2,zy:.8,px:.2,py:.9});if(action==='book-affine')Object.assign(state,{transformBase:'book',func:'affine',alpha:3,shift:-7});if(action==='similarity-original')Object.assign(state,{va:0,vb:.8,vc:1.6});if(action==='similarity-boundary')Object.assign(state,{va:0,vb:.8,vc:1});if(action==='two-inequalities')Object.assign(state,{f2:0,f4:1,f5:3,g5:0,g12:0,g20:1});refresh()});
 $('advance').onclick=()=>{stop();if(audio)stopAudio();return advance()};$('reset').onclick=()=>{stop();if(audio)stopAudio();Object.assign(state,{step:0,proofStep:0,pitch:0});refresh()};$('play').onclick=()=>{if(timer){stop();return}if(audio)stopAudio();if(advance()||window.microMotion.reduced.matches)return;let count=0;timer=setInterval(()=>{if(advance()||++count>=12)stop()},1800);$('play').textContent='暂停'};
